ee:variables.ee:set-variable:
%dw 2.0
output application/json

var normalizeOrigin =
    upper(
        if (isEmpty(attributes.headers.origin default ""))
            "TIGO"
        else
            attributes.headers.origin
    )

var baseKey =
    if (!isEmpty(attributes.uriParams.idServiceAccount default ""))
        attributes.uriParams.idServiceAccount
    else if (!isEmpty(attributes.uriParams.orderNumber default ""))
        attributes.uriParams.orderNumber
    else if (!isEmpty(payload.orderNumber default ""))
        payload.orderNumber
    else if (!isEmpty(payload.idServiceAccount default ""))
        payload.idServiceAccount
    else
        ""

var keyObjectStore =
    normalizeOrigin ++ "_" ++ baseKey
---
keyObjectStore

%dw 2.0
output application/json

var ordNmbr =
    if (!isEmpty(attributes.uriParams.idServiceAccount default ""))
        attributes.uriParams.idServiceAccount
    else if (!isEmpty(attributes.uriParams.orderNumber default ""))
        attributes.uriParams.orderNumber
    else if (!isEmpty(payload.orderNumber default ""))
        payload.orderNumber
    else if (!isEmpty(payload.idServiceAccount default ""))
        payload.idServiceAccount
    else
        ""
---
ordNmbr

%dw 2.0
output application/json

var firstResult = vars.resultDB[0] default {}

var mayorista = firstResult.Caracteristica_Orden filter ($.Caracteristica == "MAYORISTA")
---
((mayorista[0].Valor default "") ++ "_" ++ (firstResult.Numero_Orden default "")) == (vars.result default "")
